  "truncated": true,
  "content": "1|import { randomUUID } from 'crypto';
2|
3|/**
4| * V5 Phase P02 § 11 — `Hypothesis`/`HypothesisLedger`.
5| *
6| * Rule (doc, verbatim): "REJECTED hypothesis cannot become active again without NEW evidence."
7| * Enforced in `propose()` below — not merely documented.
8| */
9|export type HypothesisType = 'LOCALIZATION' | 'ROOT_CAUSE' | 'SOLUTION' | 'ENVIRONMENT';
10|export type HypothesisStatus = 'PROPOSED' | 'SUPPORTED' | 'CONFIRMED' | 'CONTRADICTED' | 'REJECTED' | 'STALE';
11|
12|export type Hypothesis = {
13|  hypothesisId: string;
14|  taskId: string;
15|  claim: string;
16|  type: HypothesisType;
17|  status: HypothesisStatus;
18|  supportingEvidenceIds: string[];
19|  contradictingEvidenceIds: string[];
20|  /** Evidence count present at the moment this hypothesis was last REJECTED — see `propose()`. */
21|  rejectedAtEvidenceCount?: number;
22|  createdAt: string;
23|  updatedAt: string;
24|};
25|
26|const normalizeClaim = (claim: string): string => claim.trim().toLowerCase();
27|
28|export class HypothesisLedger {
29|  private readonly hypotheses = new Map<string, Hypothesis>();
30|
31|  constructor(private readonly taskId: string) {}
32|
33|  list(): Hypothesis[] {
34|    return [...this.hypotheses.values()];
35|  }
36|
37|  findByClaim(claim: string): Hypothesis | undefined {
38|    const normalized = normalizeClaim(claim);
39|    return [...this.hypotheses.values()].find((h) => normalizeClaim(h.claim) === normalized);
40|  }
41|
42|  /**
43|   * `currentEvidenceCount` is the caller's live evidence tally (from `EvidenceStore.list().length`
44|   * at proposal time) — comparing it against `rejectedAtEvidenceCount` is how "new evidence since
45|   * rejection" is checked without this module depending on `EvidenceStore` directly.
46|   */
47|  propose(params: {
48|    claim: string;
49|    type: HypothesisType;
50|    currentEvidenceCount: number;
51|  }): { ok: true; hypothesis: Hypothesis } | { ok: false; reason: string; hypothesis: Hypothesis } {
52|    const existing = this.findByClaim(params.claim);
53|
54|    if (existing?.status === 'REJECTED') {
55|      const hasNewEvidence = params.currentEvidenceCount > (existing.rejectedAtEvidenceCount ?? 0);
56|      if (!hasNewEvidence) {
57|        return { ok: false, reason: 'rejected_without_new_evidence', hypothesis: existing };
58|      }
59|      const reactivated: Hypothesis = {
60|        ...existing,
61|        status: 'PROPOSED',
62|        updatedAt: new Date().toISOString(),
63|      };
64|      this.hypotheses.set(reactivated.hypothesisId, reactivated);
65|      return { ok: true, hypothesis: reactivated };
66|    }
67|
68|    if (existing?.status === 'CONTRADICTED') {
69|      // A single contradiction is not terminal (only REJECTED is) — re-proposing reactivates it.
70|      const reactivated: Hypothesis = { ...existing, status: 'PROPOSED', updatedAt: new Date().toISOString() };
71|      this.hypotheses.set(reactivated.hypothesisId, reactivated);
72|      return { ok: true, hypothesis: reactivated };
73|    }
74|
75|    if (existing) {
76|      return { ok: true, hypothesis: existing };
77|    }
78|
79|    const now = new Date().toISOString();
80|    const hypothesis: Hypothesis = {
81|      hypothesisId: randomUUID(),
82|      taskId: this.taskId,
83|      claim: params.claim,
84|      type: params.type,
85|      status: 'PROPOSED',
86|      supportingEvidenceIds: [],
87|      contradictingEvidenceIds: [],
88|      createdAt: now,
89|      updatedAt: now,
90|    };
91|    this.hypotheses.set(hypothesis.hypothesisId, hypothesis);
92|    return { ok: true, hypothesis };
93|  }
94|
95|  /** The most recently created hypothesis still in an "active" (non-terminal) status. */
96|  mostRecentActive(): Hypothesis | undefined {
97|    return [...this.hypotheses.values()]
98|      .filter((h) => h.status === 'PROPOSED' || h.status === 'SUPPORTED')
99|      .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
100|  }
101|
102|  support(hypothesisId: string, evidenceId: string): void {
103|    const h = this.hypotheses.get(hypothesisId);
104|    if (!h) return;
105|    this.hypotheses.set(hypothesisId, {
106|      ...h,
107|      status: h.status === 'PROPOSED' ? 'SUPPORTED' : h.status,
108|      supportingEvidenceIds: [...h.supportingEvidenceIds, evidenceId],
109|      updatedAt: new Date().toISOString(),
110|    });
111|  }
112|
113|  confirm(hypothesisId: string, evidenceId: string): void {
114|    const h = this.hypotheses.get(hypothesisId);
115|    if (!h) return;
116|    this.hypotheses.set(hypothesisId, {
117|      ...h,
118|      status: 'CONFIRMED',
119|      supportingEvidenceIds: [...h.supportingEvidenceIds, evidenceId],
120|      updatedAt: new Date().toISOString(),"
}
